package ds4

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"strings"

	"github.com/easel/fizeau/internal/provider/openai"
	"github.com/easel/fizeau/internal/provider/registry"
	"github.com/easel/fizeau/internal/provider/utilization"
)

// ds4Props mirrors the relevant fields of the ds4-server /props response.
type ds4Props struct {
	Reasoning struct {
		SupportedEfforts   []string          `json:"supported_efforts"`
		Aliases            map[string]string `json:"aliases"`
		Default            string            `json:"default"`
		EffectiveDefault   string            `json:"effective_default"`
		ThinkMaxMinContext int               `json:"think_max_min_context"`
	} `json:"reasoning"`
	API struct {
		SupportedRequestParameters []string `json:"supported_request_parameters"`
	} `json:"api"`
	Sampling map[string]any `json:"sampling"`
	Runtime  map[string]any `json:"runtime"`
}

// Introspect fetches GET /props from a ds4-server and returns structured
// ProviderIntrospection. Returns an error if the endpoint is unreachable or
// the response is malformed; callers should fall through to static defaults.
//
// Effective reasoning levels are derived by removing alias source keys from
// supported_efforts (e.g. low/medium/xhigh all alias to high, leaving ["high", "max"]).
func Introspect(ctx context.Context, baseURL, model string, client *http.Client) (*registry.ProviderIntrospection, error) {
	if client == nil {
		client = http.DefaultClient
	}
	endpoint := utilization.ServerRoot(baseURL) + "/props"
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, endpoint, nil)
	if err != nil {
		return nil, fmt.Errorf("ds4 introspection: build request: %w", err)
	}
	resp, err := client.Do(req)
	if err != nil {
		return nil, fmt.Errorf("ds4 introspection: GET %s: %w", endpoint, err)
	}
	defer resp.Body.Close()
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		body, _ := io.ReadAll(io.LimitReader(resp.Body, 256))
		return nil, fmt.Errorf("ds4 introspection: HTTP %d: %s", resp.StatusCode, strings.TrimSpace(string(body)))
	}
	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return nil, fmt.Errorf("ds4 introspection: read body: %w", err)
	}

	var props ds4Props
	if err := json.Unmarshal(body, &props); err != nil {
		return nil, fmt.Errorf("ds4 introspection: unmarshal: %w", err)
	}

	// Effective levels = supported_efforts minus alias source keys.
	effectiveLevels := make([]string, 0, len(props.Reasoning.SupportedEfforts))
	for _, effort := range props.Reasoning.SupportedEfforts {
		if _, isAlias := props.Reasoning.Aliases[effort]; !isAlias {
			effectiveLevels = append(effectiveLevels, effort)
		}
	}

	var raw map[string]any
	_ = json.Unmarshal(body, &raw)

	return &registry.ProviderIntrospection{
		EffectiveThinkingFormat:  string(openai.ThinkingWireFormatOpenAIEffort),
		EffectiveReasoningLevels: effectiveLevels,
		AliasMap:                 props.Reasoning.Aliases,
		SupportedRequestParams:   props.API.SupportedRequestParameters,
		Raw:                      raw,
	}, nil
}

package core

import (
	"errors"
	"fmt"
)

// ErrProviderCapabilityMissing is the sentinel for a provider/server reporting
// that a feature required to serve the request is not implemented for the
// active model+config combination (for example, mlx_lm's
// "NotImplementedError: RotatingKVCache Quantization NYI"). The condition is
// deterministic for a given provider+model, so the agent loop must not retry.
var ErrProviderCapabilityMissing = errors.New("agent: provider capability missing")

// ProviderCapabilityMissingErrorCode is the stable string code carried on
// ProviderCapabilityMissingError.Code so external callers can pattern-match
// without depending on Go type identity.
const ProviderCapabilityMissingErrorCode = "PROVIDER_CAPABILITY_MISSING"

// ProviderCapabilityMissingError reports that an upstream provider rejected
// the request because the server cannot implement a capability the model
// requires under the current configuration. It carries a stable Code, the
// extracted Capability name (when one can be parsed out of the server
// message), and the raw ServerMessage so logs and tests can inspect either.
//
// Use errors.As to extract Code/Capability/ServerMessage in routing or
// telemetry; errors.Is(err, ErrProviderCapabilityMissing) matches without
// requiring callers to know the concrete struct.
type ProviderCapabilityMissingError struct {
	// Code is the stable error code; always equals ProviderCapabilityMissingErrorCode.
	Code string
	// Capability is the missing capability name extracted from the server
	// message (e.g. "RotatingKVCache Quantization"). Empty when the upstream
	// message did not name a recognizable capability.
	Capability string
	// ServerMessage is the raw error message returned by the upstream server.
	ServerMessage string
	// Cause is the underlying transport error, preserved for chained Unwrap
	// callers that want the original SDK error.
	Cause error
}

func (e *ProviderCapabilityMissingError) Error() string {
	if e.Capability != "" {
		return fmt.Sprintf("agent: provider capability missing: server cannot serve request (%s); upstream said: %s",
			e.Capability, e.ServerMessage)
	}
	return fmt.Sprintf("agent: provider capability missing: upstream said: %s", e.ServerMessage)
}

// Unwrap reports the sentinel so errors.Is(err, ErrProviderCapabilityMissing)
// works through wrapping. Use UnwrapCause for the underlying transport error.
func (e *ProviderCapabilityMissingError) Unwrap() error {
	return ErrProviderCapabilityMissing
}

// UnwrapCause returns the underlying transport error captured at classification.
func (e *ProviderCapabilityMissingError) UnwrapCause() error {
	return e.Cause
}

func (e *ProviderCapabilityMissingError) Is(target error) bool {
	switch target {
	case ErrProviderCapabilityMissing:
		return true
	}
	switch target.(type) {
	case *ProviderCapabilityMissingError:
		return true
	}
	return false
}

package llamaserver

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"strings"

	"github.com/easel/fizeau/internal/provider/openai"
	"github.com/easel/fizeau/internal/provider/registry"
	"github.com/easel/fizeau/internal/provider/utilization"
)

// llamaProps mirrors the relevant fields of the llama-server /props response.
type llamaProps struct {
	DefaultGenerationSettings struct {
		Params struct {
			ReasoningFormat string `json:"reasoning_format"`
		} `json:"params"`
	} `json:"default_generation_settings"`
	ChatTemplate     string `json:"chat_template"`
	ChatTemplateCaps struct {
		SupportsPreserveReasoning bool `json:"supports_preserve_reasoning"`
	} `json:"chat_template_caps"`
	BuildInfo map[string]any `json:"build_info"`
}

// Introspect fetches GET /props from a llama-server and returns structured
// ProviderIntrospection. Returns an error if the endpoint is unreachable or
// the response is malformed; callers should fall through to static defaults.
//
// The chat_template is inspected for the "enable_thinking" substring to
// confirm the Qwen chat_template_kwargs envelope (vs bare top-level fields).
func Introspect(ctx context.Context, baseURL, model string, client *http.Client) (*registry.ProviderIntrospection, error) {
	if client == nil {
		client = http.DefaultClient
	}
	endpoint := utilization.ServerRoot(baseURL) + "/props"
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, endpoint, nil)
	if err != nil {
		return nil, fmt.Errorf("llama-server introspection: build request: %w", err)
	}
	resp, err := client.Do(req)
	if err != nil {
		return nil, fmt.Errorf("llama-server introspection: GET %s: %w", endpoint, err)
	}
	defer resp.Body.Close()
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		body, _ := io.ReadAll(io.LimitReader(resp.Body, 256))
		return nil, fmt.Errorf("llama-server introspection: HTTP %d: %s", resp.StatusCode, strings.TrimSpace(string(body)))
	}
	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return nil, fmt.Errorf("llama-server introspection: read body: %w", err)
	}

	var props llamaProps
	if err := json.Unmarshal(body, &props); err != nil {
		return nil, fmt.Errorf("llama-server introspection: unmarshal: %w", err)
	}

	// Detect Qwen chat_template_kwargs envelope via substring match.
	// Top-level enable_thinking is silently dropped by llama-server; the
	// kwargs envelope (chat_template_kwargs.enable_thinking) is required.
	thinkingFormat := openai.ThinkingWireFormatQwen
	if !strings.Contains(props.ChatTemplate, "enable_thinking") {
		// Template doesn't reference enable_thinking at all — reasoning
		// controls may not apply. Qwen remains the default for this provider
		// type; callers can override via catalog L2.
		thinkingFormat = openai.ThinkingWireFormatQwen
	}

	var raw map[string]any
	_ = json.Unmarshal(body, &raw)

	return &registry.ProviderIntrospection{
		EffectiveThinkingFormat:   string(thinkingFormat),
		ServerSideReasoningFormat: props.DefaultGenerationSettings.Params.ReasoningFormat,
		Raw:                       raw,
	}, nil
}

package reasoning

import (
	"encoding/json"
	"fmt"
	"math"
	"strconv"
	"strings"

	"gopkg.in/yaml.v3"
)

// Reasoning is the canonical scalar for model-side reasoning controls.
type Reasoning string

const (
	ReasoningAuto    Reasoning = "auto"
	ReasoningOff     Reasoning = "off"
	ReasoningLow     Reasoning = "low"
	ReasoningMedium  Reasoning = "medium"
	ReasoningHigh    Reasoning = "high"
	ReasoningMinimal Reasoning = "minimal"
	ReasoningXHigh   Reasoning = "xhigh"
	ReasoningMax     Reasoning = "max"
)

// PortableBudgets are fallback named reasoning token budgets.
var PortableBudgets = map[Reasoning]int{
	ReasoningOff:    0,
	ReasoningLow:    2048,
	ReasoningMedium: 8192,
	ReasoningHigh:   32768,
}

// ReasoningTokens returns a numeric reasoning-token request.
func ReasoningTokens(n int) Reasoning {
	return Reasoning(strconv.Itoa(n))
}

type Kind string

const (
	KindUnset  Kind = "unset"
	KindAuto   Kind = "auto"
	KindOff    Kind = "off"
	KindNamed  Kind = "named"
	KindTokens Kind = "tokens"
)

type Policy struct {
	Kind   Kind
	Value  Reasoning
	Tokens int
}

type ResolutionSource string

const (
	ResolutionSourceCaller  ResolutionSource = "caller"
	ResolutionSourceSnapped ResolutionSource = "snapped"
	ResolutionSourceDefault ResolutionSource = "default"
)

type SupportedResolution struct {
	Policy    Policy
	Source    ResolutionSource
	Warning   string
	Reason    string
	Supported []Reasoning
}

func (p Policy) IsSet() bool {
	return p.Kind != KindUnset
}

func (p Policy) IsExplicitOff() bool {
	return p.Kind == KindOff || (p.Kind == KindTokens && p.Tokens == 0)
}

func Normalize(value string) (Reasoning, error) {
	p, err := ParseString(value)
	if err != nil {
		return "", err
	}
	return p.Value, nil
}

func ParseString(value string) (Policy, error) {
	s := strings.ToLower(strings.TrimSpace(value))
	if s == "" {
		return Policy{Kind: KindUnset}, nil
	}
	switch s {
	case "auto":
		return Policy{Kind: KindAuto, Value: ReasoningAuto}, nil
	case "off", "none", "false":
		return Policy{Kind: KindOff, Value: ReasoningOff}, nil
	case "low":
		return Policy{Kind: KindNamed, Value: ReasoningLow}, nil
	case "medium":
		return Policy{Kind: KindNamed, Value: ReasoningMedium}, nil
	case "high":
		return Policy{Kind: KindNamed, Value: ReasoningHigh}, nil
	case "minimal":
		return Policy{Kind: KindNamed, Value: ReasoningMinimal}, nil
	case "x-high", "x_high", "xhigh":
		return Policy{Kind: KindNamed, Value: ReasoningXHigh}, nil
	case "max":
		return Policy{Kind: KindNamed, Value: ReasoningMax}, nil
	}
	tokens, err := strconv.Atoi(s)
	if err == nil {
		if tokens < 0 {
			return Policy{}, fmt.Errorf("reasoning: negative token budget %d is invalid", tokens)
		}
		if tokens == 0 {
			return Policy{Kind: KindOff, Value: ReasoningOff, Tokens: 0}, nil
		}
		return Policy{Kind: KindTokens, Value: ReasoningTokens(tokens), Tokens: tokens}, nil
	}
	return Policy{}, fmt.Errorf("reasoning: unsupported value %q", value)
}

func Parse(value any) (Policy, error) {
	switch v := value.(type) {
	case nil:
		return Policy{Kind: KindUnset}, nil
	case Reasoning:
		return ParseString(string(v))
	case string:
		return ParseString(v)
	case int:
		return ParseString(strconv.Itoa(v))
	case int64:
		return ParseString(strconv.FormatInt(v, 10))
	case float64:
		if v != float64(int(v)) {
			return Policy{}, fmt.Errorf("reasoning: numeric value %v must be an integer", v)
		}
		return ParseString(strconv.Itoa(int(v)))
	case json.Number:
		i, err := strconv.Atoi(v.String())
		if err != nil {
			return Policy{}, fmt.Errorf("reasoning: numeric value %q must be an integer", v.String())
		}
		return ParseString(strconv.Itoa(i))
	default:
		return Policy{}, fmt.Errorf("reasoning: unsupported scalar type %T", value)
	}
}

// BudgetForNamed returns the PortableBudgets token budget for a named reasoning
// tier. Returns 0 for tiers without a portable budget (off, minimal, xhigh, max).
func BudgetForNamed(r Reasoning) int {
	return PortableBudgets[r]
}

// NearestTierForTokens snaps a token count to the nearest PortableBudgets tier
// using log2-scale distance; ties round up to the higher tier.
// Boundaries (geometric midpoints): <4096 → low, [4096,16384) → medium, ≥16384 → high.
func NearestTierForTokens(n int) Reasoning {
	if n < 4096 {
		return ReasoningLow
	}
	if n < 16384 {
		return ReasoningMedium
	}
	return ReasoningHigh
}

// ResolveAgainstSupportedLevels validates a caller policy against discovered
// harness reasoning levels. Empty or unparsable support lists deliberately keep
// the existing behavior: the caller policy is returned unchanged.
func ResolveAgainstSupportedLevels(policy Policy, supportedLevels []string) (SupportedResolution, error) {
	supported := normalizeSupportedLevels(supportedLevels)
	source := ResolutionSourceCaller
	if policy.Kind == KindUnset || policy.Kind == KindAuto {
		source = ResolutionSourceDefault
	}
	out := SupportedResolution{
		Policy:    policy,
		Source:    source,
		Supported: supported,
	}
	if len(supported) == 0 {
		return out, nil
	}
	switch policy.Kind {
	case KindUnset, KindAuto, KindOff:
		return out, nil
	case KindTokens:
		tier := NearestTierForTokens(policy.Tokens)
		if containsReasoning(supported, tier) {
			out.Policy = Policy{Kind: KindNamed, Value: tier}
			out.Source = ResolutionSourceSnapped
			out.Reason = "tokens_converted_to_effort"
			return out, nil
		}
		snapped, ok := nearestSupportedTier(tier, supported)
		if !ok {
			return out, nil
		}
		out.Policy = Policy{Kind: KindNamed, Value: snapped}
		out.Source = ResolutionSourceSnapped
		out.Reason = "tokens_converted_and_snapped_to_supported_effort"
		out.Warning = fmt.Sprintf("reasoning effort %q from %d tokens is not supported; snapped to %q", tier, policy.Tokens, snapped)
		return out, nil
	case KindNamed:
		if containsReasoning(supported, policy.Value) {
			return out, nil
		}
		snapped, ok := nearestSupportedTier(policy.Value, supported)
		if !ok {
			return out, nil
		}
		out.Policy = Policy{Kind: KindNamed, Value: snapped}
		out.Source = ResolutionSourceSnapped
		out.Reason = "unsupported_effort_snapped_to_nearest_supported"
		out.Warning = fmt.Sprintf("reasoning effort %q is not supported; snapped to %q", policy.Value, snapped)
		return out, nil
	default:
		return SupportedResolution{}, fmt.Errorf("reasoning: unsupported policy kind %q", policy.Kind)
	}
}

func normalizeSupportedLevels(levels []string) []Reasoning {
	out := make([]Reasoning, 0, len(levels))
	for _, level := range levels {
		policy, err := ParseString(level)
		if err != nil {
			continue
		}
		switch policy.Kind {
		case KindOff, KindNamed:
			if !containsReasoning(out, policy.Value) {
				out = append(out, policy.Value)
			}
		}
	}
	return out
}

func containsReasoning(values []Reasoning, value Reasoning) bool {
	for _, candidate := range values {
		if candidate == value {
			return true
		}
	}
	return false
}

