package openai

// Protocol-level capability flags describe what the concrete provider can
// honor on the OpenAI-compatible wire: tool calls, streaming, and structured
// output modes. They are distinct from routing-layer capability (a
// benchmark-quality score used by smart routing). Callers use these flags to
// gate dispatch before sending unsupported request shapes.

// ProtocolCapabilities declares provider-owned protocol capability claims.
type ProtocolCapabilities struct {
	Tools            bool
	Stream           bool
	StructuredOutput bool
	// Thinking reports whether the provider accepts non-standard body fields
	// (openai-go WithJSONSet) used to control model-side reasoning.
	Thinking       bool
	ThinkingFormat ThinkingWireFormat
	// StrictThinkingModelMatch, when true, makes the openai layer return an
	// error if the request carries an explicit reasoning policy while the
	// model does not match the provider's wire format family (e.g. a Qwen
	// wire format with a non-Qwen model). Set true for providers that only
	// serve a single model family (OMLX → Qwen MLX). Providers that host
	// mixed model families (LM Studio can load Qwen, Gemma, Llama, etc.)
	// should leave this false so reasoning controls silently no-op on
	// non-matching models instead of failing the request.
	StrictThinkingModelMatch bool
	// ImplicitGenerationConfig declares that the inference server applies
	// the model's HuggingFace `generation_config.json` automatically when
	// the request omits sampler fields. vLLM does this by default; most
	// other local servers (omlx, lmstudio, lucebox) ship custom presets and
	// either ignore upstream defaults or replace them at repackage time
	// (MLX / GGUF strip generation_config.json), which is why ADR-007's
	// catalog sampling_profiles exist. Routing and the catalog-stale
	// nudge use this flag to distinguish "server has a sane default" from
	// "server will decode greedy" when no catalog profile is supplied.
	ImplicitGenerationConfig bool
	// ReasoningAliasMap carries the L1 alias map from live introspection.
	// Keys are caller-visible tiers and values are canonical tiers.
	ReasoningAliasMap map[string]string
	// SupportedRequestParams carries the L1 supported-request-parameter list
	// from live introspection. The translator uses it as an additional hint
	// when the explicit ThinkingFormat is absent.
	SupportedRequestParams []string
}

type ThinkingWireFormat string

const (
	// ThinkingWireFormatThinkingMap sends `thinking: {type, budget_tokens}`.
	ThinkingWireFormatThinkingMap ThinkingWireFormat = "thinking_map"
	// ThinkingWireFormatQwen sends Qwen-family controls:
	// `enable_thinking` and `thinking_budget`.
	ThinkingWireFormatQwen ThinkingWireFormat = "qwen"
	// ThinkingWireFormatOpenRouter sends OpenRouter's nested `reasoning`
	// object with `effort`, `max_tokens`, or `exclude`.
	ThinkingWireFormatOpenRouter ThinkingWireFormat = "openrouter"
	// ThinkingWireFormatOpenAIEffort sends flat top-level
	// `reasoning_effort: "<tier>"`. Disable form: top-level `think: false`.
	// Used by ds4 / deepseek-v4-flash.
	ThinkingWireFormatOpenAIEffort ThinkingWireFormat = "openai_effort"
)

var (
	OpenAIProtocolCapabilities  = ProtocolCapabilities{Tools: true, Stream: true, StructuredOutput: true, Thinking: false}
	UnknownProtocolCapabilities ProtocolCapabilities
)

func (p *Provider) protocolCapabilities() ProtocolCapabilities {
	if p.capabilities != nil {
		return *p.capabilities
	}
	return OpenAIProtocolCapabilities
}

// SupportsTools reports whether the concrete provider accepts a `tools`
// field on `/v1/chat/completions` and returns structured `tool_calls` in the
// response.
func (p *Provider) SupportsTools() bool {
	return p.protocolCapabilities().Tools
}

// SupportsStream reports whether `stream: true` returns a well-formed SSE
// stream with incremental `choices[0].delta` chunks.
func (p *Provider) SupportsStream() bool {
	return p.protocolCapabilities().Stream
}

// SupportsStructuredOutput reports whether the provider honors
// `response_format: json_object` / tool-use-required semantics to produce a
// structured (JSON-shaped) response.
func (p *Provider) SupportsStructuredOutput() bool {
	return p.protocolCapabilities().StructuredOutput
}

// SupportsThinking reports whether the provider accepts non-standard request
// body fields used to cap or disable model-side reasoning. Providers returning
// false MUST have those fields stripped at serialization time.
func (p *Provider) SupportsThinking() bool {
	return p.protocolCapabilities().Thinking
}

func (p *Provider) thinkingWireFormat() ThinkingWireFormat {
	caps := p.protocolCapabilities()
	if !caps.Thinking {
		return ""
	}
	if caps.ThinkingFormat != "" {
		return caps.ThinkingFormat
	}
	if hasSupportedRequestParam(caps.SupportedRequestParams, "reasoning_effort") ||
		hasSupportedRequestParam(caps.SupportedRequestParams, "think") {
		return ThinkingWireFormatOpenAIEffort
	}
	if hasSupportedRequestParam(caps.SupportedRequestParams, "enable_thinking") ||
		hasSupportedRequestParam(caps.SupportedRequestParams, "thinking_budget") {
		return ThinkingWireFormatQwen
	}
	if hasSupportedRequestParam(caps.SupportedRequestParams, "budget_tokens") ||
		hasSupportedRequestParam(caps.SupportedRequestParams, "thinking") {
		return ThinkingWireFormatThinkingMap
	}
	return ThinkingWireFormatThinkingMap
}

func hasSupportedRequestParam(params []string, target string) bool {
	for _, param := range params {
		if param == target {
			return true
		}
	}
	return false
}

func (p *Provider) strictThinkingModelMatch() bool {
	return p.protocolCapabilities().StrictThinkingModelMatch
}

// ImplicitGenerationConfig reports whether the provider's server applies a
// model-card-derived sampler bundle (`generation_config.json`) when the
// request omits sampler fields. Used by the agent CLI to tone the
// catalog-stale nudge per ADR-007 §7.
func (p *Provider) ImplicitGenerationConfig() bool {
	return p.protocolCapabilities().ImplicitGenerationConfig
}

package reasoning

import "testing"

func TestParseReasoningNormalizesScalarValues(t *testing.T) {
	tests := []struct {
		name  string
		input any
		kind  Kind
		value Reasoning
		tok   int
	}{
		{name: "empty", input: "", kind: KindUnset},
		{name: "auto", input: "auto", kind: KindAuto, value: ReasoningAuto},
		{name: "off", input: "off", kind: KindOff, value: ReasoningOff},
		{name: "none", input: "none", kind: KindOff, value: ReasoningOff},
		{name: "false", input: "false", kind: KindOff, value: ReasoningOff},
		{name: "zero string", input: "0", kind: KindOff, value: ReasoningOff},
		{name: "zero int", input: 0, kind: KindOff, value: ReasoningOff},
		{name: "low", input: "low", kind: KindNamed, value: ReasoningLow},
		{name: "medium", input: "medium", kind: KindNamed, value: ReasoningMedium},
		{name: "high", input: "high", kind: KindNamed, value: ReasoningHigh},
		{name: "minimal", input: "minimal", kind: KindNamed, value: ReasoningMinimal},
		{name: "x-high", input: "x-high", kind: KindNamed, value: ReasoningXHigh},
		{name: "max", input: "max", kind: KindNamed, value: ReasoningMax},
		{name: "tokens string", input: "1234", kind: KindTokens, value: Reasoning("1234"), tok: 1234},
		{name: "tokens int", input: 1234, kind: KindTokens, value: Reasoning("1234"), tok: 1234},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, err := Parse(tt.input)
			if err != nil {
				t.Fatalf("Parse(%v) returned error: %v", tt.input, err)
			}
			if got.Kind != tt.kind || got.Value != tt.value || got.Tokens != tt.tok {
				t.Fatalf("Parse(%v) = %#v, want kind=%s value=%q tokens=%d", tt.input, got, tt.kind, tt.value, tt.tok)
			}
		})
	}
}

func TestBudgetForPortableDefaults(t *testing.T) {
	tests := []struct {
		value Reasoning
		want  int
	}{
		{ReasoningLow, 2048},
		{ReasoningMedium, 8192},
		{ReasoningHigh, 32768},
		{ReasoningTokens(4096), 4096},
	}
	for _, tt := range tests {
		policy, err := Parse(tt.value)
		if err != nil {
			t.Fatalf("Parse(%q): %v", tt.value, err)
		}
		got, err := BudgetFor(policy, nil, 0)
		if err != nil {
			t.Fatalf("BudgetFor(%q): %v", tt.value, err)
		}
		if got != tt.want {
			t.Fatalf("BudgetFor(%q) = %d, want %d", tt.value, got, tt.want)
		}
	}
}

func TestBudgetForRejectsOverLimitAndUnsupportedNamedValues(t *testing.T) {
	policy, err := Parse(ReasoningTokens(4096))
	if err != nil {
		t.Fatal(err)
	}
	if _, err := BudgetFor(policy, nil, 2048); err == nil {
		t.Fatal("expected over-limit numeric budget to fail")
	}

	policy, err = Parse(ReasoningXHigh)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := BudgetFor(policy, nil, 0); err == nil {
		t.Fatal("expected unsupported extended named value to fail without provider map")
	}
}

func TestBudgetForNamed(t *testing.T) {
	tests := []struct {
		tier Reasoning
		want int
	}{
		{ReasoningLow, 2048},
		{ReasoningMedium, 8192},
		{ReasoningHigh, 32768},
		{ReasoningOff, 0},
		{ReasoningMinimal, 0},
		{ReasoningXHigh, 0},
		{ReasoningMax, 0},
	}
	for _, tt := range tests {
		t.Run(string(tt.tier), func(t *testing.T) {
			got := BudgetForNamed(tt.tier)
			if got != tt.want {
				t.Fatalf("BudgetForNamed(%q) = %d, want %d", tt.tier, got, tt.want)
			}
		})
	}
}

func TestNearestTierForTokens(t *testing.T) {
	tests := []struct {
		tokens int
		want   Reasoning
	}{
		{1, ReasoningLow},
		{2048, ReasoningLow},
		{4095, ReasoningLow},
		// 4096 = geometric midpoint of 2048 and 8192; ties round up → medium
		{4096, ReasoningMedium},
		{4097, ReasoningMedium},
		{8192, ReasoningMedium},
		{16383, ReasoningMedium},
		// 16384 = geometric midpoint of 8192 and 32768; ties round up → high
		{16384, ReasoningHigh},
		{32768, ReasoningHigh},
		{100000, ReasoningHigh},
	}
	for _, tt := range tests {
		t.Run(string(ReasoningTokens(tt.tokens)), func(t *testing.T) {
			got := NearestTierForTokens(tt.tokens)
			if got != tt.want {
				t.Fatalf("NearestTierForTokens(%d) = %q, want %q", tt.tokens, got, tt.want)
			}
		})
	}
}

func TestResolveAgainstSupportedLevelsSnapsUnsupportedNamedTier(t *testing.T) {
	policy, err := ParseString("high")
	if err != nil {
		t.Fatal(err)
	}
	got, err := ResolveAgainstSupportedLevels(policy, []string{"low", "medium"})
	if err != nil {
		t.Fatal(err)
	}
	if got.Policy.Value != ReasoningMedium {
		t.Fatalf("resolved effort = %q, want medium", got.Policy.Value)
	}
	if got.Source != ResolutionSourceSnapped {
		t.Fatalf("source = %q, want snapped", got.Source)
	}
	if got.Warning == "" {
		t.Fatal("expected warning")
	}
}

func TestResolveAgainstSupportedLevelsKeepsSupportedNamedTier(t *testing.T) {
	policy, err := ParseString("high")
	if err != nil {
		t.Fatal(err)
	}
	got, err := ResolveAgainstSupportedLevels(policy, []string{"low", "medium", "high"})
	if err != nil {
		t.Fatal(err)
	}
	if got.Policy.Value != ReasoningHigh {
		t.Fatalf("resolved effort = %q, want high", got.Policy.Value)
	}
	if got.Source != ResolutionSourceCaller {
		t.Fatalf("source = %q, want caller", got.Source)
	}
	if got.Warning != "" {
		t.Fatalf("warning = %q, want empty", got.Warning)
	}
}

func TestResolveAgainstSupportedLevelsEmptySupportFallsThrough(t *testing.T) {
	policy, err := ParseString("high")
	if err != nil {
		t.Fatal(err)
	}
	got, err := ResolveAgainstSupportedLevels(policy, nil)
	if err != nil {
		t.Fatal(err)
	}
	if got.Policy != policy {
		t.Fatalf("policy = %#v, want unchanged %#v", got.Policy, policy)
	}
	if got.Warning != "" {
		t.Fatalf("warning = %q, want empty", got.Warning)
	}
}

package session

import (
	"encoding/json"
	"fmt"
	"log/slog"
	"os"
	"path/filepath"
	"sync"

	agent "github.com/easel/fizeau/internal/core"
	"github.com/easel/fizeau/internal/safefs"
)

// Logger writes session events to a JSONL file.
type Logger struct {
	dir       string
	sessionID string
	mu        sync.Mutex
	file      *os.File
	seq       int
	warned    bool
}

// NewLogger creates a Logger that writes to the given directory.
// If the directory does not exist, it is created. If creation fails,
// the logger will silently skip writes (best-effort logging).
func NewLogger(dir, sessionID string) *Logger {
	l := &Logger{
		dir:       dir,
		sessionID: sessionID,
	}
	if err := safefs.MkdirAll(dir, 0o750); err != nil {
		slog.Warn("session logger: cannot create directory", "dir", dir, "err", err)
		l.warned = true
		return l
	}
	path := filepath.Join(dir, sessionID+".jsonl")
	f, err := safefs.Create(path)
	if err != nil {
		slog.Warn("session logger: cannot create file", "path", path, "err", err)
		l.warned = true
		return l
	}
	l.file = f
	return l
}

// Callback returns an EventCallback suitable for agent.Request.Callback.
func (l *Logger) Callback() agent.EventCallback {
	return func(e agent.Event) {
		l.Write(e)
	}
}

// Emit creates and writes an event with auto-incrementing sequence number.
func (l *Logger) Emit(eventType agent.EventType, data any) {
	l.mu.Lock()
	seq := l.seq
	l.seq++
	l.mu.Unlock()

	event := NewEvent(l.sessionID, seq, eventType, data)
	l.Write(event)
}

// Write appends a pre-built event to the log file.
func (l *Logger) Write(e agent.Event) {
	l.mu.Lock()
	defer l.mu.Unlock()

	if l.file == nil {
		return
	}

	line, err := json.Marshal(e)
	if err != nil {
		if !l.warned {
			slog.Warn("session logger: marshal error", "err", err)
			l.warned = true
		}
		return
	}
	line = append(line, '\n')
	if _, err := l.file.Write(line); err != nil {
		if !l.warned {
			slog.Warn("session logger: write error", "err", err)
			l.warned = true
		}
	}
}

// Close flushes and closes the log file.
func (l *Logger) Close() error {
	l.mu.Lock()
	defer l.mu.Unlock()
	if l.file == nil {
		return nil
	}
	file := l.file
	l.file = nil
	return file.Close()
}

// ReadEvents reads all events from a session log file.
func ReadEvents(path string) ([]agent.Event, error) {
	data, err := safefs.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("session: reading log: %w", err)
	}

	var events []agent.Event
	dec := json.NewDecoder(jsonlReader(data))
	for dec.More() {
		var e agent.Event
		if err := dec.Decode(&e); err != nil {
			return events, fmt.Errorf("session: decoding event: %w", err)
		}
		events = append(events, e)
	}
	return events, nil
}

package session

import (
	"encoding/json"
	"fmt"
	"io"
	"strings"

	agent "github.com/easel/fizeau/internal/core"
)

// Replay reads a session log and renders a human-readable conversation.
func Replay(path string, w io.Writer) error {
	events, err := ReadEvents(path)
	if err != nil {
		return fmt.Errorf("replay: %w", err)
	}

	for _, e := range events {
		switch e.Type {
		case agent.EventLLMRequest:
			var data LLMRequestData
			if err := json.Unmarshal(e.Data, &data); err != nil {
				continue
			}
			fmt.Fprintf(w, "\n[LLM Request] (%d messages, %d tools)\n", len(data.Messages), len(data.Tools))
			for _, m := range data.Messages {
				switch m.Role {
				case agent.RoleSystem:
					fmt.Fprintf(w, "  [system] %s\n", m.Content)
				case agent.RoleUser:
					fmt.Fprintf(w, "  [user] %s\n", m.Content)
				case agent.RoleAssistant:
					if m.Content != "" {
						fmt.Fprintf(w, "  [assistant] %s\n", m.Content)
					}
					for _, tc := range m.ToolCalls {
						fmt.Fprintf(w, "  [assistant tool_call] %s(%s)\n", tc.Name, compactJSON(tc.Arguments))
					}
				case agent.RoleTool:
					content := m.Content
					if len(content) > 200 {
						content = content[:200] + "...[truncated]"
					}
					fmt.Fprintf(w, "  [tool result] %s\n", strings.ReplaceAll(content, "\n", "\n              "))
				}
			}

		case agent.EventSessionStart:
			var data SessionStartData
			if err := json.Unmarshal(e.Data, &data); err != nil {
				continue
			}
			fmt.Fprintf(w, "=== Session %s ===\n", e.SessionID)
			fmt.Fprintf(w, "Time: %s\n", e.Timestamp.Format("2006-01-02 15:04:05 UTC"))
			fmt.Fprintf(w, "Provider: %s | Model: %s\n", data.Provider, data.Model)
			if data.SelectedEndpoint != "" {
				fmt.Fprintf(w, "Selected endpoint: %s\n", data.SelectedEndpoint)
			}
			if data.SelectedServerInstance != "" {
				fmt.Fprintf(w, "Selected server instance: %s\n", data.SelectedServerInstance)
			}
			if data.Sticky.KeyPresent || data.Sticky.Assignment != "" || data.Sticky.Reason != "" {
				fmt.Fprintf(w, "Sticky: key=%s assignment=%s",
					routingStickyLabel(data.Sticky.KeyPresent),
					labelOrUnknown(data.Sticky.Assignment))
				if data.Sticky.Reason != "" {
					fmt.Fprintf(w, " reason=%s", data.Sticky.Reason)
				}
				if data.Sticky.Bonus != 0 {
					fmt.Fprintf(w, " bonus=%.2f", data.Sticky.Bonus)
				}
				fmt.Fprintln(w)
			}
			if data.Utilization.Source != "" || data.Utilization.Freshness != "" ||
				data.Utilization.ActiveRequests != nil || data.Utilization.QueuedRequests != nil ||
				data.Utilization.MaxConcurrency != nil || data.Utilization.CachePressure != nil {
				fmt.Fprintf(w, "Utilization: source=%s freshness=%s",
					labelOrUnknown(data.Utilization.Source),
					labelOrUnknown(data.Utilization.Freshness))
				if data.Utilization.ActiveRequests != nil {
					fmt.Fprintf(w, " active=%d", *data.Utilization.ActiveRequests)
				}
				if data.Utilization.QueuedRequests != nil {
					fmt.Fprintf(w, " queued=%d", *data.Utilization.QueuedRequests)
				}
				if data.Utilization.MaxConcurrency != nil {
					fmt.Fprintf(w, " max=%d", *data.Utilization.MaxConcurrency)
				}
				if data.Utilization.CachePressure != nil {
					fmt.Fprintf(w, " cache_pressure=%.2f", *data.Utilization.CachePressure)
				}
				fmt.Fprintln(w)
			}
			fmt.Fprintf(w, "Max iterations: %d | Work dir: %s\n", data.MaxIterations, data.WorkDir)
			if data.SystemPrompt != "" {
				fmt.Fprintf(w, "\n[System]\n%s\n", data.SystemPrompt)
			}
			fmt.Fprintf(w, "\n[User]\n%s\n", data.Prompt)

		case agent.EventLLMResponse:
			var data LLMResponseData
			if err := json.Unmarshal(e.Data, &data); err != nil {
				continue
			}
			fmt.Fprintf(w, "\n[Assistant] (%dms, %d in / %d out tokens",
				data.LatencyMs, data.Usage.Input, data.Usage.Output)
			if data.CostUSD > 0 {
				fmt.Fprintf(w, ", $%.4f", data.CostUSD)
			}
			fmt.Fprintf(w, ")\n")
			if data.Content != "" {
				fmt.Fprintf(w, "%s\n", data.Content)
			}
			if len(data.ToolCalls) > 0 {
				fmt.Fprintf(w, "[%d tool call(s)]\n", len(data.ToolCalls))
			}

		case agent.EventToolCall:
			var data ToolCallData
			if err := json.Unmarshal(e.Data, &data); err != nil {
				continue
			}
			fmt.Fprintf(w, "\n  > %s (%dms)\n", data.Tool, data.DurationMs)
			fmt.Fprintf(w, "    Input:  %s\n", compactJSON(data.Input))
			output := data.Output
			if len(output) > 200 {
				output = output[:200] + "...[truncated]"
			}
			fmt.Fprintf(w, "    Output: %s\n", strings.ReplaceAll(output, "\n", "\n            "))
			if data.Error != "" {
				fmt.Fprintf(w, "    Error:  %s\n", data.Error)
			}

		case agent.EventSessionEnd:
			var data SessionEndData
			if err := json.Unmarshal(e.Data, &data); err != nil {
				continue
			}
			fmt.Fprintf(w, "\n=== End (%s) ===\n", data.Status)
			if data.Model != "" {
				fmt.Fprintf(w, "Model: %s\n", data.Model)
			}
			if data.SelectedEndpoint != "" {
				fmt.Fprintf(w, "Selected endpoint: %s\n", data.SelectedEndpoint)
			}
			if data.SelectedServerInstance != "" {
				fmt.Fprintf(w, "Selected server instance: %s\n", data.SelectedServerInstance)
			}
			fmt.Fprintf(w, "Duration: %dms | Tokens: %d in / %d out",
				data.DurationMs, data.Tokens.Input, data.Tokens.Output)
			if data.CostUSD == nil || *data.CostUSD < 0 {
				fmt.Fprintf(w, " | Cost: unknown")
			} else if *data.CostUSD > 0 {
				fmt.Fprintf(w, " | Cost: $%.4f", *data.CostUSD)
			} else {
				fmt.Fprintf(w, " | Cost: $0 (local)")
			}
			fmt.Fprintln(w)
			if len(data.Metadata) > 0 {
				fmt.Fprintf(w, "Metadata:")
				for k, v := range data.Metadata {
					fmt.Fprintf(w, " %s=%s", k, v)
				}
				fmt.Fprintln(w)
			}
			if data.Error != "" {
				fmt.Fprintf(w, "Error: %s\n", data.Error)
			}
		}
	}
	return nil
}

func routingStickyLabel(present bool) string {
	if present {
		return "present"
	}
	return "absent"
}

func labelOrUnknown(v string) string {
	if v == "" {
		return "unknown"
	}
	return v
}

func compactJSON(raw json.RawMessage) string {
	var v any
	if json.Unmarshal(raw, &v) != nil {
		return string(raw)
	}
	data, _ := json.Marshal(v)
	return string(data)
}

