func applyReasoningAliasMap(policy reasoningpolicy.Policy, aliasMap map[string]string) (reasoningpolicy.Policy, bool) {
	if policy.Kind != reasoningpolicy.KindNamed || len(aliasMap) == 0 {
		return policy, false
	}
	mapped, ok := aliasMap[string(policy.Value)]
	if !ok || mapped == "" || mapped == string(policy.Value) {
		return policy, false
	}
	return reasoningpolicy.Policy{
		Kind:  reasoningpolicy.KindNamed,
		Value: reasoningpolicy.Reasoning(mapped),
	}, true
}

// reasoningRequestOptions builds per-request options. For thinking models
// (Qwen3, DeepSeek-R1 etc.) apply provider-specific non-standard body fields
// only when the concrete provider declares the matching wire support.
func (p *Provider) reasoningRequestOptions(model string, opts agent.Options) ([]option.RequestOption, error) {
	policy, err := reasoningpolicy.Parse(opts.Reasoning)
	if err != nil {
		return nil, err
	}
	explicitRequest := policy.IsSet()
	if !explicitRequest {
		policy, err = reasoningpolicy.Parse(p.reasoningDefault)
		if err != nil {
			return nil, err
		}
	}

	if !policy.IsSet() || policy.Kind == reasoningpolicy.KindAuto {
		return nil, nil
	}

	// Catalog reasoning_wire metadata gates the wire shape before any
	// provider-specific encoding runs. Models flagged as reasoning_wire=none
	// have no reasoning surface at all; an explicit non-off request is a
	// catalog/wire mismatch and must surface as an error rather than be
	// silently dropped. Models flagged as reasoning_wire=model_id encode the
	// reasoning level in the model name (e.g. fixed-variant Qwen3.6) and the
	// upstream endpoint cannot honor an external reasoning toggle, so the
	// reasoning field must be stripped from the wire body.
	catalogWire := p.modelReasoningWireFor(model)
	switch catalogWire {
	case "none":
		if explicitRequest && !policy.IsExplicitOff() {
			return nil, fmt.Errorf("openai: model %q has reasoning_wire=none; explicit reasoning=%q is not supported", model, policy.Value)
		}
		return nil, nil
	case "model_id":
		return nil, nil
	}

	if !p.SupportsThinking() {
		if policy.IsExplicitOff() {
			return nil, nil
		}
		if explicitRequest {
			return nil, fmt.Errorf("openai: reasoning=%q is not supported by provider type %q", policy.Value, p.providerSystem)
		}
		return nil, nil
	}

	if policy.IsExplicitOff() {
		switch p.thinkingWireFormat() {
		case ThinkingWireFormatQwen:
			if !isQwenModel(model) {
				if explicitRequest && p.strictThinkingModelMatch() {
					return nil, fmt.Errorf("openai: qwen reasoning control is not supported for model %q on provider type %q", model, p.providerSystem)
				}
				return nil, nil
			}
			return []option.RequestOption{
				option.WithJSONSet("chat_template_kwargs", map[string]interface{}{
					"enable_thinking": false,
				}),
			}, nil
		case ThinkingWireFormatOpenRouter:
			return []option.RequestOption{option.WithJSONSet("reasoning", map[string]interface{}{
				"effort": "none",
			})}, nil
		case ThinkingWireFormatOpenAIEffort:
			return []option.RequestOption{option.WithJSONSet("think", false)}, nil
		}
		return nil, nil
	}

	if p.thinkingWireFormat() == ThinkingWireFormatOpenRouter {
		return openRouterReasoningOptions(policy, model, catalogWire)
	}
	if p.thinkingWireFormat() == ThinkingWireFormatOpenAIEffort {
		return openAIEffortReasoningOptions(policy, p.protocolCapabilities().ReasoningAliasMap, p.logger, model, p.providerSystem)
	}
	if p.thinkingWireFormat() == ThinkingWireFormatQwen && !isQwenModel(model) {
		if explicitRequest && p.strictThinkingModelMatch() {
			return nil, fmt.Errorf("openai: qwen reasoning control is not supported for model %q on provider type %q", model, p.providerSystem)
		}
		return nil, nil
	}

	// Qwen and ThinkingMap providers can only express a token budget on the
	// wire. If the catalog declares effort wire for this model, degrade
	// gracefully: snap KindTokens to the nearest PortableBudgets tier so the
	// downstream budget calculation uses a standard value. The model still
	// works; the catalog entry is simply mis-classified.
	if catalogWire == "effort" {
		p.logger.Warn("catalog declares effort wire but provider only supports budget wire",
			"model", model,
			"provider", p.providerSystem,
		)
		if policy.Kind == reasoningpolicy.KindTokens {
			tier := reasoningpolicy.NearestTierForTokens(policy.Tokens)
			policy = reasoningpolicy.Policy{Kind: reasoningpolicy.KindNamed, Value: tier}
		}
	}

	thinkingBudget, err := reasoningpolicy.BudgetFor(policy, nil, 0)
	if err != nil {
		return nil, fmt.Errorf("openai: %w", err)
	}
	if thinkingBudget <= 0 {
		return nil, nil
	}

	switch p.thinkingWireFormat() {
	case ThinkingWireFormatQwen:
		return []option.RequestOption{
			option.WithJSONSet("chat_template_kwargs", map[string]interface{}{
				"enable_thinking": true,
				"thinking_budget": thinkingBudget,
			}),
		}, nil
	case "", ThinkingWireFormatThinkingMap:
		return []option.RequestOption{option.WithJSONSet("thinking", map[string]interface{}{
			"type":          "enabled",
			"budget_tokens": thinkingBudget,
		})}, nil
	default:
		return nil, fmt.Errorf("openai: unsupported thinking wire format %q for provider type %q", p.thinkingWireFormat(), p.providerSystem)
	}
}

// openAIEffortReasoningOptions builds the flat top-level reasoning_effort wire
// used by ds4 / deepseek-v4-flash. Named tiers are emitted as-is; token
// budgets are snapped to the nearest PortableBudgets tier via NearestTierForTokens.
// Alias maps from live introspection are applied after snapping so ds4's
// low/medium/xhigh→high aliasing is reflected on the wire.
func openAIEffortReasoningOptions(policy reasoningpolicy.Policy, aliasMap map[string]string, logger *slog.Logger, model, providerSystem string) ([]option.RequestOption, error) {
	var tier reasoningpolicy.Reasoning
	switch policy.Kind {
	case reasoningpolicy.KindTokens:
		tier = reasoningpolicy.NearestTierForTokens(policy.Tokens)
	case reasoningpolicy.KindNamed:
		tier = policy.Value
	default:
		return nil, fmt.Errorf("openai: unsupported OpenAI effort reasoning policy kind %q", policy.Kind)
	}
	normalized, changed := applyReasoningAliasMap(reasoningpolicy.Policy{Kind: reasoningpolicy.KindNamed, Value: tier}, aliasMap)
	if changed && logger != nil {
		logger.Warn("reasoning alias map overrode requested tier",
			"model", model,
			"provider", providerSystem,
			"reasoning_intent", string(tier),
			"reasoning_emitted", string(normalized.Value),
			"reasoning_emitted_reason", providerSystem+" alias map",
		)
		tier = normalized.Value
	}
	return []option.RequestOption{option.WithJSONSet("reasoning_effort", string(tier))}, nil
}

// modelReasoningWireFor returns the catalog reasoning_wire value for the
// given model, defaulting to "provider" when the model is not catalog-known.
// Returned values are normalized: only "model_id" and "none" trigger
// catalog-driven wire overrides; everything else falls through to the
// provider's protocol capability path.
func (p *Provider) modelReasoningWireFor(model string) string {
	if p.modelReasoningWire == nil || model == "" {
		return ""
	}
	return p.modelReasoningWire[model]
}

func isQwenModel(model string) bool {
	return strings.Contains(strings.ToLower(model), "qwen")
}

// openRouterReasoningOptions builds the OpenRouter nested reasoning object.
// model is included for structured-warning logs.
// wire is the catalog reasoning_wire value for the model:
//   - "" or "provider": pick wire shape from policy.Kind (backwards-compat)
//   - "effort": always emit reasoning.effort string; snap KindTokens to nearest tier
//   - "tokens": always emit reasoning.max_tokens int; expand KindNamed via PortableBudgets
func openRouterReasoningOptions(policy reasoningpolicy.Policy, model, wire string) ([]option.RequestOption, error) {
	reasoning := map[string]interface{}{}
	switch wire {
	case "effort":
		var tier reasoningpolicy.Reasoning
		switch policy.Kind {
		case reasoningpolicy.KindTokens:
			tier = reasoningpolicy.NearestTierForTokens(policy.Tokens)
		case reasoningpolicy.KindNamed:
			tier = policy.Value
			if tier == reasoningpolicy.ReasoningMax {
				tier = reasoningpolicy.ReasoningXHigh
			}
		default:
			return nil, fmt.Errorf("openai: unsupported OpenRouter reasoning policy %q for effort wire", policy.Kind)
		}
		effort := string(tier)
		switch effort {
		case "minimal", "low", "medium", "high", "xhigh":
			reasoning["effort"] = effort
		default:
			return nil, fmt.Errorf("openai: unsupported OpenRouter reasoning effort %q", tier)
		}
	case "tokens":
		var budget int
		switch policy.Kind {
		case reasoningpolicy.KindTokens:
			budget = policy.Tokens
		case reasoningpolicy.KindNamed:
			budget = reasoningpolicy.BudgetForNamed(policy.Value)
			if budget <= 0 {
				return nil, fmt.Errorf("openai: named reasoning %q has no portable token budget for tokens wire", policy.Value)
			}
		default:
			return nil, fmt.Errorf("openai: unsupported OpenRouter reasoning policy %q for tokens wire", policy.Kind)
		}
		reasoning["max_tokens"] = budget
	default:
		// "" or "provider": today's behavior — pick wire shape from policy.Kind.
		switch policy.Kind {
		case reasoningpolicy.KindTokens:
			reasoning["max_tokens"] = policy.Tokens
		case reasoningpolicy.KindNamed:
			effort := string(policy.Value)
			if policy.Value == reasoningpolicy.ReasoningMax {
				effort = string(reasoningpolicy.ReasoningXHigh)
			}
			switch effort {
			case "minimal", "low", "medium", "high", "xhigh":
				reasoning["effort"] = effort
			default:
				return nil, fmt.Errorf("openai: unsupported OpenRouter reasoning effort %q", policy.Value)
			}
		default:
			return nil, fmt.Errorf("openai: unsupported OpenRouter reasoning policy %q", policy.Kind)
		}
	}
	return []option.RequestOption{option.WithJSONSet("reasoning", reasoning)}, nil
}

var _ agent.Provider = (*Provider)(nil)
var _ agent.StreamingProvider = (*Provider)(nil)

func endpointMetadata(baseURL string) (serverAddress string, serverPort int) {
	serverAddress = "api.openai.com"
	serverPort = 443

	if baseURL == "" {
		return serverAddress, serverPort
	}

	parsed, err := url.Parse(baseURL)
	if err != nil {
		return serverAddress, serverPort
	}

// Package registry is the single source of truth for provider-type →
// factory mappings.
//
// Why this package exists. Before it, the agent had two parallel
// factories that knew about provider types: internal/config/config.go
// `BuildProvider` (config-time) and service_native_provider.go
// `buildNativeProvider` (service-execute time). When lucebox + vllm
// were added in v0.9.18-.20, only the first factory got the new types;
// the second one rejected requests pinning those providers at execute
// time. Two factories drifting is the architectural smell `agent-8e4eb44c`
// was filed to fix.
//
// Each provider package registers a Descriptor in its init(). Both
// factories call Lookup. New providers are one Register call away from
// being usable through every code path.
//
// The registry deliberately covers only the factory drift case in v1.
// Other type-switch sites (default port, base URL, surface map,
// capability flags, validators) are local to internal/config and
// don't have the cross-package drift problem; they stay there. Future
// drift cases can be additively folded into the registry as they appear.
package registry

import (
	"sort"
	"sync"

	agentcore "github.com/easel/fizeau/internal/core"
	"github.com/easel/fizeau/internal/provider/quotaheaders"
	"github.com/easel/fizeau/internal/reasoning"
)

// Inputs is the canonical factory input shape. Both the config-time
// path (internal/config builds this from a ProviderConfig) and the
// service-time path (service_native_provider builds this from a
// ServiceProviderEntry) populate it. Provider factories take exactly
// one argument so the call sites can't accidentally diverge.
type Inputs struct {
	// ProviderName is the user-facing config name for this provider
	// (e.g., "vidar-omlx"). Distinct from the provider TYPE (e.g.,
	// "omlx"). Some factories include it in attribution metadata.
	ProviderName string

	// BaseURL is the resolved endpoint (with default substituted).
	BaseURL string
	// APIKey is the bearer token; empty for unauthenticated endpoints.
	APIKey string
	// Model is the configured default; empty when discovery is in use.
	Model string

	// ModelPattern is an optional regex used by openai-compat providers
	// during model discovery (Tier-2 ranking).
	ModelPattern string

	// KnownModels maps surface model IDs to canonical IDs from the
	// model catalog. Used by openai-compat providers to recognize
	// catalog-tracked models on a discovery list.
	KnownModels map[string]string

	// Headers is extra HTTP headers (OpenRouter, Azure, custom).
	Headers map[string]string

	// Reasoning is the per-provider default reasoning policy.
	Reasoning reasoning.Reasoning

	// ModelReasoningWire is a model_id → reasoning_wire map sourced
	// from the catalog. Today only openrouter and openai-compat
	// providers consume it; others ignore it.
	ModelReasoningWire map[string]string

	// QuotaSignalObserver, when set, is forwarded to provider factories
	// that support per-response rate-limit-header parsing (anthropic,
	// openai, openrouter). The service layer wires this to the provider
	// quota state machine so dispatch can route around providers whose
	// subscription/daily cap is hit. Providers that do not parse rate-limit
	// headers ignore this field.
	QuotaSignalObserver func(quotaheaders.Signal)
}

// Factory builds a provider from canonical inputs.
type Factory func(Inputs) agentcore.Provider

// Descriptor pairs a provider type with its factory + a small set of
// invariants. Provider packages register these in init().
type Descriptor struct {
	// Type is the canonical provider-type string (e.g., "omlx").
	// Matches the `type:` value in user config and the descriptor's
	// case in internal/config switches.
	Type string

	// Factory builds an agent.Provider from canonical inputs.
	Factory Factory

	// DefaultBaseURL is used by the config-normalizer when no base_url
	// is explicitly set.
	DefaultBaseURL string

	// DefaultPort is used by endpoint-config inference when only a
	// host is supplied. 0 means "no inference; require explicit BaseURL".
	DefaultPort int

	// IntrospectionFn, when non-nil, is the L1 live-introspection adapter
	// for this provider type. Register automatically wires it into the
	// introspection adapter map so IntrospectProvider can invoke it.
	IntrospectionFn IntrospectionFn
}

var (
	mu      sync.RWMutex
	entries = map[string]Descriptor{}
)

// Register installs a provider Descriptor. Called from each provider
// package's init() function. Re-registering the same type panics —
// duplicate registration is always a programmer error.
func Register(d Descriptor) {
	if d.Type == "" {
		panic("provider/registry: Descriptor.Type is required")
	}
	if d.Factory == nil {
		panic("provider/registry: Descriptor.Factory is required for type " + d.Type)
	}
	mu.Lock()
	defer mu.Unlock()
	if _, exists := entries[d.Type]; exists {
		panic("provider/registry: duplicate registration for type " + d.Type)
	}
	entries[d.Type] = d
	if d.IntrospectionFn != nil {
		RegisterIntrospectionAdapter(d.Type, d.IntrospectionFn)
	}
}

// Lookup returns the Descriptor for a provider type, or false if the
// type is not registered.
func Lookup(typ string) (Descriptor, bool) {
	mu.RLock()
	defer mu.RUnlock()
	d, ok := entries[typ]
	return d, ok
}

// Types returns all registered provider type names in sorted order.
// Used by validators and conformance descriptors that iterate over
// every known provider type.
func Types() []string {
	mu.RLock()
	defer mu.RUnlock()
	out := make([]string, 0, len(entries))
	for t := range entries {
		out = append(out, t)
	}
	sort.Strings(out)
	return out
}

// the per-type switch is gone — both this and service_native_provider's
// buildNativeProvider go through registry.Lookup. Adding a new
// provider type is one Register() call in the new package.
func buildProviderFromConfig(pc ProviderConfig) (agent.Provider, error) {
	pc = normalizeProviderConfig(pc)
	d, ok := provregistry.Lookup(pc.Type)
	if !ok {
		return nil, fmt.Errorf("config: unknown provider type %q", pc.Type)
	}
	return d.Factory(provregistry.Inputs{
		ProviderName:       pc.Type,
		BaseURL:            pc.BaseURL,
		APIKey:             pc.APIKey,
		Model:              pc.Model,
		ModelPattern:       pc.ModelPattern,
		KnownModels:        openAIKnownModels(),
		Headers:            pc.Headers,
		Reasoning:          pc.Reasoning,
		ModelReasoningWire: modelReasoningWireMap()[string(modelcatalog.SurfaceAgentOpenAI)],
	}), nil
}

// LookupModelLimits queries the concrete provider package for provider-owned
// model limits. Unknown or unsupported providers return zero values.
func LookupModelLimits(ctx context.Context, pc ProviderConfig, model string) limits.ModelLimits {
	pc = normalizeProviderConfig(pc)
	switch pc.Type {
	case "openrouter":
		return openrouter.LookupModelLimits(ctx, pc.BaseURL, pc.APIKey, pc.Headers, model)
	case "lmstudio":
		return lmstudio.LookupModelLimits(ctx, pc.BaseURL, model)
	case "omlx":
		return omlx.LookupModelLimits(ctx, pc.BaseURL, model)
	default:
		return limits.ModelLimits{}
	}
}

func openAIKnownModels() map[string]string {
	if cat, err := modelcatalog.Default(); err == nil {
		return cat.AllConcreteModels(modelcatalog.SurfaceAgentOpenAI)
	}
	return nil
}

// modelReasoningWireMap returns a surface-system → surface-model-ID →
// reasoning_wire map sourced from the embedded catalog. Models without an
// explicit reasoning_wire field are omitted (the provider treats absence as
// the "provider" default).
//
// Keying by surface ID (e.g., "qwen/qwen3.6-27b") rather than catalog ID
// ("qwen3.6-27b") fixes the lookup mismatch: providers query by the model
// string they actually send on the wire, which is the surface ID, not the
// catalog key.
func modelReasoningWireMap() map[string]map[string]string {
	cat, err := modelcatalog.Default()
	if err != nil {
		return nil
	}
	all := cat.AllModels()
	if len(all) == 0 {
		return nil
	}
	out := make(map[string]map[string]string)
	for _, entry := range all {
		if entry.ReasoningWire == "" {
			continue
		}
		for surface, surfaceID := range entry.Surfaces {
			if out[surface] == nil {
				out[surface] = make(map[string]string)
			}
			out[surface][surfaceID] = entry.ReasoningWire
		}
	}
	return out
}

func rejectLegacyProviderReasoningKeys(data []byte) error {
	var raw struct {
		Providers map[string]map[string]any `yaml:"providers"`
	}
	if err := yaml.Unmarshal(data, &raw); err != nil {
		return err
	}
	for name, provider := range raw.Providers {
		if _, ok := provider["flavor"]; ok {
			return fmt.Errorf("provider %q: flavor is no longer supported; use a concrete provider type", name)
		}
		for _, key := range []string{"thinking" + "_level", "thinking" + "_budget"} {
			if _, ok := provider[key]; ok {
				return fmt.Errorf("provider %q: use reasoning instead of %s", name, key)
			}
		}
	}
	return nil
}

func (c *Config) finalize() error {
	c.warnings = nil
	c.providerErrors = nil

// Package ds4 wraps the OpenAI-compatible HTTP surface exposed by DwarfStar 4
// (antirez/ds4) — a single-model native inference engine for DeepSeek V4 Flash
// with Metal/CUDA execution. The /v1/chat/completions and /v1/completions
// routes are OpenAI-compatible; /v1/messages also speaks Anthropic Messages.
// Other endpoints (no /health, /metrics, /slots, no auth) are minimal —
// see internal/provider/ds4/utilization_probe.go for the liveness-only probe.
package ds4

import (
	"context"
	"time"

	agentcore "github.com/easel/fizeau/internal/core"
	"github.com/easel/fizeau/internal/provider/openai"
	"github.com/easel/fizeau/internal/provider/registry"
	"github.com/easel/fizeau/internal/reasoning"
)

// DefaultBaseURL matches the ds4-server default listen (127.0.0.1:8000) plus
// the /v1 prefix. Operators usually override the host portion in their
// fizeau provider config; the port stays 8000 unless the server was started
// with --port.
const DefaultBaseURL = "http://localhost:8000/v1"

func init() {
	registry.Register(registry.Descriptor{
		Type: "ds4",
		Factory: func(in registry.Inputs) agentcore.Provider {
			return New(Config{
				BaseURL:      in.BaseURL,
				APIKey:       in.APIKey,
				Model:        in.Model,
				ModelPattern: in.ModelPattern,
				KnownModels:  in.KnownModels,
				Headers:      in.Headers,
				Reasoning:    in.Reasoning,
			})
		},
		DefaultBaseURL:  DefaultBaseURL,
		DefaultPort:     8000,
		IntrospectionFn: Introspect,
	})
}

// ProtocolCapabilities is the L3 static default for ds4. It is used as the
// base when no live introspection is available. ds4's verified wire surface
// (via /props):
//   - `reasoning_effort: "low"|"medium"|"high"|"max"|"xhigh"` (flat top-level, OpenAI-style)
//   - `think: false` (boolean shortcut for direct-reply / disable)
//   - model alias `deepseek-chat` for non-thinking
//
// ds4 /props.reasoning.aliases declares {low→high, medium→high, xhigh→high};
// only `high` and `max` are practically distinct effort levels.
// fizeau emits ThinkingWireFormatOpenAIEffort (flat reasoning_effort) for this provider.
//
// Other ds4 quirks worth knowing about (handled elsewhere): finish_reason
// is only "stop" or "length" — never "tool_calls" — but the agent loop
// already keys on empty resp.ToolCalls for natural-stop detection.
var ProtocolCapabilities = openai.ProtocolCapabilities{
	Tools:            true,
	Stream:           true,
	StructuredOutput: true,
	Thinking:         true,
	ThinkingFormat:   openai.ThinkingWireFormatOpenAIEffort,
}

type Config struct {
	BaseURL      string
	APIKey       string
	Model        string
	ModelPattern string
	KnownModels  map[string]string
	Headers      map[string]string
	Reasoning    reasoning.Reasoning
}

// New constructs a ds4 provider. It first attempts L1 live introspection via
// /props to override static capability defaults (e.g. ThinkingFormat). On
// introspection failure the static ProtocolCapabilities are used unchanged.
func New(cfg Config) *openai.Provider {
	baseURL := cfg.BaseURL
	if baseURL == "" {
		baseURL = DefaultBaseURL
	}

	// Start from the L3 static defaults; L1 introspection may override.
	caps := ProtocolCapabilities

	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	if intro, ok := registry.IntrospectProvider(ctx, "ds4", baseURL, cfg.Model); ok {
		if intro.EffectiveThinkingFormat != "" {
			caps.ThinkingFormat = openai.ThinkingWireFormat(intro.EffectiveThinkingFormat)
		}
		caps.ReasoningAliasMap = intro.AliasMap
		caps.SupportedRequestParams = intro.SupportedRequestParams
	}

	return openai.New(openai.Config{
		BaseURL:        baseURL,
		APIKey:         cfg.APIKey,
		Model:          cfg.Model,
		ProviderName:   "ds4",
		ProviderSystem: "ds4",
		ModelPattern:   cfg.ModelPattern,
		KnownModels:    cfg.KnownModels,
		Headers:        cfg.Headers,
		Reasoning:      cfg.Reasoning,
		Capabilities:   &caps,
	})
}

