		"attempted_providers": result.AttemptedProviders,
		"failover_count":      result.FailoverCount,
		"metadata":            metadata,
		"error":               errStr,
	}
	if result.CostUSD >= 0 {
		data["cost_usd"] = result.CostUSD
	}
	emitCallback(cb, Event{
		SessionID: sessionID,
		Seq:       *seq,
		Type:      EventSessionEnd,
		Timestamp: time.Now().UTC(),
		Data:      mustMarshal(data),
	})
	*seq++
}

